CREATE TABLE IF NOT EXISTS bronze.users (user_id Int64, full_name String, email String, city String, country String, created_at DateTime('UTC'), _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY user_id;
CREATE TABLE IF NOT EXISTS bronze.user_history (history_id Int64, user_id Int64, full_name String, email String, city String, country String, valid_from DateTime('UTC'), valid_to DateTime('UTC'), _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY history_id;
CREATE TABLE IF NOT EXISTS bronze.instructors (instructor_id Int64, full_name String, expertise String, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY instructor_id;
CREATE TABLE IF NOT EXISTS bronze.courses (course_id Int64, instructor_id Int64, title String, category String, difficulty String, price_vnd Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY course_id;
CREATE TABLE IF NOT EXISTS bronze.lessons (lesson_id Int64, course_id Int64, title String, position Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY lesson_id;
CREATE TABLE IF NOT EXISTS bronze.quizzes (quiz_id Int64, course_id Int64, title String, total_questions Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY quiz_id;
CREATE TABLE IF NOT EXISTS bronze.payment_methods (method_id Int64, method_name String, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY method_id;
CREATE TABLE IF NOT EXISTS bronze.enrollments (enrollment_id Int64, user_id Int64, course_id Int64, enrolled_at DateTime('UTC'), completed_at Nullable(DateTime('UTC')), lessons_completed Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY enrollment_id;
CREATE TABLE IF NOT EXISTS bronze.payments (payment_id Int64, enrollment_id Int64, user_id Int64, course_id Int64, method_id Int64, transaction_id String, paid_at DateTime('UTC'), original_vnd Int64, discount_vnd Int64, charged_vnd Int64, refunded Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY payment_id;
CREATE TABLE IF NOT EXISTS bronze.lesson_completions (completion_id Int64, enrollment_id Int64, user_id Int64, course_id Int64, lesson_id Int64, completed_at DateTime('UTC'), time_spent_seconds Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY completion_id;
CREATE TABLE IF NOT EXISTS bronze.quiz_attempts (attempt_id Int64, enrollment_id Int64, user_id Int64, course_id Int64, quiz_id Int64, attempt_number Int64, attempted_at DateTime('UTC'), correct_count Int64, total_questions Int64, time_spent_seconds Int64, _run_id String, _loaded_at DateTime('UTC'), _source String) ENGINE=MergeTree ORDER BY attempt_id;
CREATE TABLE IF NOT EXISTS silver.users (user_id Int64, full_name String, email String, city String, country String, created_at DateTime('UTC')) ENGINE=MergeTree ORDER BY user_id;
CREATE TABLE IF NOT EXISTS silver.user_history (history_id Int64, user_id Int64, full_name String, email String, city String, country String, valid_from DateTime('UTC'), valid_to DateTime('UTC')) ENGINE=MergeTree ORDER BY history_id;
