CREATE TABLE IF NOT EXISTS silver.lessons (lesson_id Int64, course_id Int64, title String, position Int64) ENGINE=MergeTree ORDER BY lesson_id;
CREATE TABLE IF NOT EXISTS silver.quizzes (quiz_id Int64, course_id Int64, title String, total_questions Int64) ENGINE=MergeTree ORDER BY quiz_id;
CREATE TABLE IF NOT EXISTS silver.payment_methods (method_id Int64, method_name String) ENGINE=MergeTree ORDER BY method_id;
CREATE TABLE IF NOT EXISTS silver.enrollments (enrollment_id Int64, user_id Int64, course_id Int64, enrolled_at DateTime('UTC'), completed_at Nullable(DateTime('UTC')), lessons_completed Int64) ENGINE=MergeTree ORDER BY enrollment_id;
CREATE TABLE IF NOT EXISTS silver.payments (payment_id Int64, enrollment_id Int64, user_id Int64, course_id Int64, method_id Int64, transaction_id String, paid_at DateTime('UTC'), original_vnd Int64, discount_vnd Int64, charged_vnd Int64, refunded Int64) ENGINE=MergeTree ORDER BY payment_id;
CREATE TABLE IF NOT EXISTS silver.lesson_completions (completion_id Int64, enrollment_id Int64, user_id Int64, course_id Int64, lesson_id Int64, completed_at DateTime('UTC'), time_spent_seconds Int64) ENGINE=MergeTree ORDER BY completion_id;
CREATE TABLE IF NOT EXISTS silver.quiz_attempts (attempt_id Int64, enrollment_id Int64, user_id Int64, course_id Int64, quiz_id Int64, attempt_number Int64, attempted_at DateTime('UTC'), correct_count Int64, total_questions Int64, time_spent_seconds Int64) ENGINE=MergeTree ORDER BY attempt_id;
